// Node's own resolution rule sends this require to vt2-init-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw. This is RWF-016's callee, unchanged -- what RWF-018 is about is
// the POSITION the call is written in, below.
function bail() {
  throw new Error("fast mode is not supported by this build");
}

// A same-name decoy nested inside a function that is never called at
// module scope. Real JS lexical scoping never resolves the module-scope
// call below to this one, and the deferred body never runs at load time
// either -- so it changes no answer, and the oracle does not depend on it.
function configure() {
  function bail() {
    return "configured";
  }
  // A class carrying the exact RWF-018 shape, DEFERRED inside a function
  // body: `configure` is never called at module scope, so this class is
  // never evaluated during module evaluation and must poison nothing.
  class Deferred {
    static probe = bail();
  }
  return Deferred;
}

// An INSTANCE field carrying the identical call, evaluated at module scope.
// Evaluating this class definition INSTALLS the initializer and runs
// nothing -- `bail()` executes only inside `new Installed()`, which nothing
// here does. An analyzer that conflates instance initialization with static
// class evaluation would cut module evaluation off HERE, above the fast
// branch, and would then refuse the fast branch's own export too -- turning
// the whole file unanalyzable for the wrong reason and hiding whether it
// models the real rule at all.
class Installed {
  ready = bail();
}

// A static field with NO initializer, and an ordinary static METHOD whose
// body throws. Neither executes anything at class-definition time, so
// neither may cut module evaluation off either.
class Probe {
  static pending;
  static blow() {
    throw new Error("only when called");
  }
}

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // The RWF-018 shape. The call is in neither statement position RWF-016
  // and RWF-017 recognise -- it is the initializer of a class STATIC
  // FIELD. Evaluating a class definition runs its static elements in
  // declaration order as part of that evaluation, so `stage` initializes,
  // then this necessarily invokes `bail`, which never returns. The class
  // definition never completes, `Mode` is never bound, `trailing` never
  // initializes, and module evaluation on this branch ends here.
  class Mode {
    static stage = "fast";
    static ready = bail();
    static trailing = "never initialized";
  }
}

// Reached on every OTHER load, and on no load where the branch above was
// taken. Syntactically this is exactly what RWF-014 accepted: a bare
// identifier assigned by an unconditional top-level statement, last in the
// file, with no deferred write anywhere -- and RWF-015's return/throw
// cutoff, RWF-016's bare-call cutoff and RWF-017's variable-initializer
// cutoff all find nothing here to object to either, since the file
// contains no module-scope `return`/`throw`, no bare `bail();` statement
// and no `const x = bail();` declaration at all.
module.exports = slowPath;
